            const n = aiNorm(q).replace(/\s+/g, ' ');
            if (!SEC_RE.test(n)) return null;
            const log = secGet('agmk_sec_log', []);
            log.unshift({ at: new Date().toISOString(), tabel: me.tabel, name: me.name, role: me.role, q: String(q).slice(0, 300), seen: false });
            secSet('agmk_sec_log', log.slice(0, 500));
            if (me.tabel === ADMIN_TABEL) return "⛔ Bu mumkin emas: xavfsizlik yuzasidan cheklov o'rnatilgan. AI dastur sozlamalari, parollar va ma'lumotlarga ta'sir qila olmaydi. (Administrator — so'rov jurnalga yozildi.)";
            const cnt = log.filter(x => x.tabel === me.tabel && !x.cleared).length;
            if (cnt <= 1) return "⛔ Bu mumkin emas. Xavfsizlik yuzasidan cheklov o'rnatilgan: AI dastur sozlamalari, parollar, hisoblar va ma'lumotlar bazasiga ta'sir qila olmaydi. So'rovingiz qayd etildi.";
            if (cnt === 2) return "⚠️ OGOHLANTIRISH! Bunday so'rov takrorlandi. Bu haqida tizim asoschisiga xabar beriladi va hisobingiz bloklanishi mumkin.";
            const off = secGet('agmk_sec_aioff', {}); off[me.tabel] = { at: new Date().toISOString() }; secSet('agmk_sec_aioff', off);
            return "⛔ Xavfsizlik qoidasi " + cnt + "-marta buzildi. AI yordamchi siz uchun yopildi, holat tizim asoschisiga yetkaziladi. Hisobingizni bloklash masalasini administrator ko'rib chiqadi.";
